cat >> crates/editor-api/tests/classic_unified.rs <<'RS'

async fn task(r: &OpenCutRuntime, action: &str, id: &str, extra: Value) -> Result<Value,String> {
    let s=read(r).await;
    let mut input=json!({"projectId":"classic-project","expectedRevision":s["revision"],"mediaId":"unified","taskId":id,"action":action});
    input.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
    r.registry().invoke("media.classic.unified.sync_task",InvocationContext::default(),input).await.map(|r|r.result.data).map_err(|e|e.to_string())
}
#[tokio::test]
async fn audio_task_progress_is_canonical_grouped_undoable_and_source_preserving() {
    let r=fixture().await;let before=read(&r).await;
    let input=json!({"projectId":"classic-project","expectedRevision":before["revision"],"mediaId":"unified","taskId":"job-a","action":"start"});
    r.registry().invoke("media.classic.unified.sync_task",InvocationContext{dry_run:true,..Default::default()},input).await.unwrap();
    assert_eq!(read(&r).await,before);
    task(&r,"start","job-a",json!({})).await.unwrap();
    let output=task(&r,"progress","job-a",json!({"progress":0.6,"stage":"Comparing waveform windows"})).await.unwrap();
    assert_eq!(output["unifiedAngles"]["syncTask"]["progress"],0.6);
    let after=read(&r).await;
    assert_eq!(after["project"]["classic"]["document"],before["project"]["classic"]["document"]);
    assert_eq!(after["project"]["classic"]["mediaAssets"][2]["unifiedAngles"]["syncTask"]["status"],"running");
    assert_eq!(after["project"]["classic"]["mediaAssets"][0],before["project"]["classic"]["mediaAssets"][0]);
    for (action,extra) in [("progress",json!({"progress":0.2})),("start",json!({})),("progress",json!({"progress":1.1}))] {
        assert!(task(&r,action,"job-a",extra).await.is_err());assert_eq!(read(&r).await,after);
    }
    call(&r,"history.undo",json!({})).await;
    assert_eq!(read(&r).await["project"],before["project"]);
    call(&r,"history.redo",json!({})).await;
